static void ui_pixel(ui_surface_t *surface, int x, int y, uint16_t color)
{
  if (surface != NULL && x >= 0 && y >= 0 && x < surface->width &&
      y < surface->height)
    {
      surface->pixels[y * surface->stride + x] = color;
    }
}

void ui_clear(ui_surface_t *surface, uint16_t color)
{
  if (surface == NULL)
    {
      return;
    }
  ui_fill_rect(surface, 0, 0, surface->width, surface->height, color);
}

void ui_fill_rect(ui_surface_t *surface, int x, int y, int width, int height,
                  uint16_t color)
{
  int x0 = x < 0 ? 0 : x;
  int y0 = y < 0 ? 0 : y;
  int x1 = x + width > surface->width ? surface->width : x + width;
  int y1 = y + height > surface->height ? surface->height : y + height;
  int row;

  if (surface == NULL || surface->pixels == NULL || x0 >= x1 || y0 >= y1)
    {
      return;
    }

  for (row = y0; row < y1; row++)
    {
      int col;
      uint16_t *dest = surface->pixels + row * surface->stride + x0;
      for (col = x0; col < x1; col++)
        {
          *dest++ = color;
        }
    }
}

void ui_rect(ui_surface_t *surface, int x, int y, int width, int height,
             int thickness, uint16_t color)
{
  ui_fill_rect(surface, x, y, width, thickness, color);
  ui_fill_rect(surface, x, y + height - thickness, width, thickness, color);
  ui_fill_rect(surface, x, y, thickness, height, color);
  ui_fill_rect(surface, x + width - thickness, y, thickness, height, color);
}

void ui_line(ui_surface_t *surface, int x0, int y0, int x1, int y1,
             uint16_t color)
{
  int dx = x1 > x0 ? x1 - x0 : x0 - x1;
  int sx = x0 < x1 ? 1 : -1;
  int dy = y1 > y0 ? y0 - y1 : y1 - y0;
  int sy = y0 < y1 ? 1 : -1;
  int error = dx + dy;

  for (;;)
    {
      int twice;
      ui_pixel(surface, x0, y0, color);
      if (x0 == x1 && y0 == y1)
        {
          break;
        }

      twice = error * 2;
      if (twice >= dy)
        {
          error += dy;
          x0 += sx;
        }

      if (twice <= dx)
        {
          error += dx;
          y0 += sy;
        }
    }
}

void ui_circle(ui_surface_t *surface, int cx, int cy, int radius,
               int thickness, uint16_t color)
{
  int outer;
  for (outer = 0; outer < thickness; outer++)
    {
      int x = radius - outer;
      int y = 0;
      int error = 1 - x;
      while (x >= y)
        {
          ui_pixel(surface, cx + x, cy + y, color);
          ui_pixel(surface, cx + y, cy + x, color);
          ui_pixel(surface, cx - y, cy + x, color);
          ui_pixel(surface, cx - x, cy + y, color);
          ui_pixel(surface, cx - x, cy - y, color);
          ui_pixel(surface, cx - y, cy - x, color);
          ui_pixel(surface, cx + y, cy - x, color);
          ui_pixel(surface, cx + x, cy - y, color);
          y++;
          if (error < 0)
            {
              error += 2 * y + 1;
            }
          else
            {
              x--;
              error += 2 * (y - x + 1);
            }
        }
    }
}

void ui_fill_circle(ui_surface_t *surface, int cx, int cy, int radius,
                    uint16_t color)
{
  int y;
  for (y = -radius; y <= radius; y++)
    {
      int x = 0;
      while ((x + 1) * (x + 1) + y * y <= radius * radius)
        {
          x++;
        }
      ui_fill_rect(surface, cx - x, cy + y, x * 2 + 1, 1, color);
    }
}

static const uint8_t *ui_glyph(char input)
{
  static const uint8_t blank[7] = {0, 0, 0, 0, 0, 0, 0};
  static const uint8_t question[7] = {14, 17, 1, 2, 4, 0, 4};
  static const uint8_t glyphs[][7] =
  {
    {14,17,19,21,25,17,14}, {4,12,4,4,4,4,14},
    {14,17,1,2,4,8,31}, {30,1,1,14,1,1,30},
    {2,6,10,18,31,2,2}, {31,16,16,30,1,1,30},
    {14,16,16,30,17,17,14}, {31,1,2,4,8,8,8},
    {14,17,17,14,17,17,14}, {14,17,17,15,1,1,14},
    {14,17,17,31,17,17,17}, {30,17,17,30,17,17,30},
    {14,17,16,16,16,17,14}, {30,17,17,17,17,17,30},
    {31,16,16,30,16,16,31}, {31,16,16,30,16,16,16},
    {14,17,16,23,17,17,15}, {17,17,17,31,17,17,17},
    {14,4,4,4,4,4,14}, {7,2,2,2,2,18,12},
    {17,18,20,24,20,18,17}, {16,16,16,16,16,16,31},
    {17,27,21,21,17,17,17}, {17,25,21,19,17,17,17},
    {14,17,17,17,17,17,14}, {30,17,17,30,16,16,16},
    {14,17,17,17,21,18,13}, {30,17,17,30,20,18,17},
    {15,16,16,14,1,1,30}, {31,4,4,4,4,4,4},
    {17,17,17,17,17,17,14}, {17,17,17,17,17,10,4},
    {17,17,17,21,21,21,10}, {17,17,10,4,10,17,17},
    {17,17,10,4,4,4,4}, {31,1,2,4,8,16,31}
  };
  unsigned char ch = (unsigned char)input;

  if (ch >= 'a' && ch <= 'z')
    {
      ch = (unsigned char)toupper(ch);
    }
  if (ch >= '0' && ch <= '9')
    {
      return glyphs[ch - '0'];
    }
  if (ch >= 'A' && ch <= 'Z')
    {
      return glyphs[10 + ch - 'A'];
    }
  if (ch == ' ')
    {
      return blank;
    }
  return question;
}

static int ui_utf8_advance(const unsigned char *text)
{
  if ((*text & 0x80) == 0) return 1;
  if ((*text & 0xe0) == 0xc0) return 2;
  if ((*text & 0xf0) == 0xe0) return 3;
  if ((*text & 0xf8) == 0xf0) return 4;
  return 1;
}

int ui_text_width(const char *text, int scale)
{
  int count = 0;
  const unsigned char *cursor = (const unsigned char *)text;
  if (text == NULL || scale < 1) return 0;
  while (*cursor != '\0')
    {
      cursor += ui_utf8_advance(cursor);
      count++;
    }
  return count == 0 ? 0 : count * 6 * scale - scale;
}

void ui_text(ui_surface_t *surface, int x, int y, const char *text, int scale,
             uint16_t color)
{
  const unsigned char *cursor = (const unsigned char *)text;
  if (text == NULL || scale < 1) return;

  while (*cursor != '\0')
    {
      int row;
      int advance = ui_utf8_advance(cursor);
      const uint8_t *glyph = advance == 1 ? ui_glyph((char)*cursor) : ui_glyph('?');
      for (row = 0; row < 7; row++)
        {
          int col;
          for (col = 0; col < 5; col++)
            {
              if ((glyph[row] & (1 << (4 - col))) != 0)
                {
                  ui_fill_rect(surface, x + col * scale, y + row * scale,
                               scale, scale, color);
                }
            }
        }
      x += 6 * scale;
      cursor += advance;
    }
}

void ui_text_center(ui_surface_t *surface, int center_x, int y,
                    const char *text, int scale, uint16_t color)
{
  ui_text(surface, center_x - ui_text_width(text, scale) / 2, y,
          text, scale, color);
}

#include "lcd_icons.h"

static void draw_phone(ui_surface_t *surface, int x, int y, uint16_t color)
{
  ui_rect(surface, x, y, 20, 34, 3, color);
  ui_fill_rect(surface, x + 7, y + 28, 6, 2, color);
}

static void draw_check(ui_surface_t *surface, int x, int y, uint16_t color)
{
  ui_line(surface, x, y + 8, x + 8, y + 16, color);
  ui_line(surface, x + 8, y + 16, x + 24, y, color);
  ui_line(surface, x, y + 9, x + 8, y + 17, color);
  ui_line(surface, x + 8, y + 17, x + 24, y + 1, color);
}

static void draw_star(ui_surface_t *surface, int cx, int cy, uint16_t color)
{
  ui_line(surface, cx, cy - 16, cx + 5, cy - 5, color);
  ui_line(surface, cx + 5, cy - 5, cx + 17, cy - 4, color);
  ui_line(surface, cx + 17, cy - 4, cx + 8, cy + 4, color);
  ui_line(surface, cx + 8, cy + 4, cx + 11, cy + 16, color);
  ui_line(surface, cx + 11, cy + 16, cx, cy + 9, color);
  ui_line(surface, cx, cy + 9, cx - 11, cy + 16, color);
  ui_line(surface, cx - 11, cy + 16, cx - 8, cy + 4, color);
  ui_line(surface, cx - 8, cy + 4, cx - 17, cy - 4, color);
  ui_line(surface, cx - 17, cy - 4, cx - 5, cy - 5, color);
  ui_line(surface, cx - 5, cy - 5, cx, cy - 16, color);
}

void lcd_draw_status_icon(ui_surface_t *surface, int x, int y,
                          uint8_t mode, status_t status)
{
  const uint16_t green = UI_RGB565(0, 200, 83);
  const uint16_t yellow = UI_RGB565(255, 214, 0);
  const uint16_t red = UI_RGB565(213, 0, 0);
  const uint16_t orange = UI_RGB565(255, 152, 0);
  const uint16_t gray = UI_RGB565(158, 158, 158);
  const uint16_t blue_gray = UI_RGB565(96, 125, 139);
  const uint16_t blue = UI_RGB565(68, 138, 255);
  uint16_t color = green;
  int cx = x + 40;
  int cy = y + 40;

  if (status == GLANCING_PHONE) color = mode == 0 ? yellow : orange;
  else if (status == PLAYING_PHONE) color = mode == 0 ? red : orange;
  else if (status == AWAY) color = mode == 0 ? gray : blue_gray;
  else if (status == DROWSY) color = blue;

  ui_rect(surface, x, y, 80, 80, 1, UI_RGB565(55, 65, 81));

  if (status == FOCUSED)
    {
      ui_circle(surface, cx, cy, 31, 3, color);
      if (mode == 0) draw_check(surface, cx - 12, cy - 8, color);
      else draw_star(surface, cx, cy, color);
    }
  else if (status == GLANCING_PHONE)
    {
      if (mode == 0)
        {
          ui_line(surface, cx, cy - 31, cx - 32, cy + 26, color);
          ui_line(surface, cx - 32, cy + 26, cx + 32, cy + 26, color);
          ui_line(surface, cx + 32, cy + 26, cx, cy - 31, color);
        }
      else
        {
          ui_circle(surface, cx, cy, 31, 3, color);
        }
      draw_phone(surface, cx - 10, cy - 16, color);
      if (mode != 0) ui_text(surface, cx + 13, cy - 18, "?", 2, color);
    }
  else if (status == PLAYING_PHONE)
    {
      ui_circle(surface, cx, cy, 31, 3, color);
      draw_phone(surface, cx - 10, cy - 17, color);
      if (mode == 0)
        {
          ui_line(surface, cx - 22, cy + 22, cx + 22, cy - 22, color);
          ui_line(surface, cx - 21, cy + 22, cx + 23, cy - 22, color);
        }
      else
        {
          ui_circle(surface, cx + 19, cy - 17, 6, 2, color);
          ui_line(surface, cx + 14, cy - 10, cx + 24, cy - 10, color);
        }
    }
  else if (status == AWAY)
    {
      if (mode == 0)
        {
          ui_line(surface, cx, cy - 32, cx + 32, cy, color);
          ui_line(surface, cx + 32, cy, cx, cy + 32, color);
          ui_line(surface, cx, cy + 32, cx - 32, cy, color);
          ui_line(surface, cx - 32, cy, cx, cy - 32, color);
          ui_rect(surface, cx - 16, cy - 5, 32, 18, 3, color);
          ui_line(surface, cx - 12, cy + 13, cx - 17, cy + 25, color);
          ui_line(surface, cx + 12, cy + 13, cx + 17, cy + 25, color);
        }
      else
        {
          ui_circle(surface, cx, cy, 31, 3, color);
          ui_rect(surface, cx - 15, cy - 22, 30, 45, 3, color);
          ui_fill_circle(surface, cx + 8, cy, 2, color);
        }
    }
  else
    {
      ui_circle(surface, cx, cy, 31, 3, color);
      if (mode == 0)
        {
          ui_text(surface, cx - 19, cy - 19, "ZZZ", 2, color);
        }
      else
        {
          ui_rect(surface, cx - 18, cy - 8, 31, 22, 3, color);
          ui_circle(surface, cx + 17, cy + 1, 8, 2, color);
          ui_line(surface, cx - 12, cy - 17, cx - 8, cy - 23, color);
